import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

bmm_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

const int TILE_SIZE = 16;

__global__ void bmm_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int batch_size, int m, int k, int n
) {
    int bid_z = blockIdx.z;
    int bid_y = blockIdx.y * TILE_SIZE + threadIdx.y;
    int bid_x = blockIdx.x * TILE_SIZE + threadIdx.x;

    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    float sum = 0.0;

    for(int t=0; t<k; t+=TILE_SIZE) {
        if(bid_y < m && (t + threadIdx.x) < k) {
            As[threadIdx.y][threadIdx.x] = A[bid_z*m*k + bid_y*k + t + threadIdx.x];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0;
        }

        if((t + threadIdx.y) < k && bid_x < n) {
            Bs[threadIdx.y][threadIdx.x] = B[bid_z*k*n + (t + threadIdx.y)*n + bid_x];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0;
        }

        __syncthreads();

        for(int i=0; i<TILE_SIZE; i++) {
            sum += As[threadIdx.y][i] * Bs[i][threadIdx.x];
        }

        __syncthreads();
    }

    if(bid_y < m && bid_x < n) {
        C[bid_z*m*n + bid_y*n + bid_x] = sum;
    }
}

torch::Tensor bmm_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 3, "A must be 3D");
    TORCH_CHECK(B.dim() == 3, "B must be 3D");

    int batch_size = A.size(0);
    int m = A.size(1);
    int k = A.size(2);
    int n = B.size(2);

    auto C = torch::zeros({batch_size, m, n}, A.options());

    dim3 grid((n + TILE_SIZE-1)/TILE_SIZE, 
             (m + TILE_SIZE-1)/TILE_SIZE, 
              batch_size);
    dim3 block(TILE_SIZE, TILE_SIZE);

    bmm_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        batch_size, m, k, n
    );

    return C;
}
"""

bmm_cpp_source = "torch::Tensor bmm_cuda(torch::Tensor A, torch::Tensor B);"

bmm_extension = load_inline(
    name="bmm_extension",
    cpp_sources=bmm_cpp_source,
    cuda_sources=bmm_cuda_source,
    functions=["bmm_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.bmm_op = bmm_extension

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.bmm_op.bmm_cuda(A, B)
